 93→func (c *Claude) Bootstrap() error {
 94→	// On CI, write a config file so Claude Code uses the API key from the
 95→	// environment instead of trying OAuth/Keychain.
 96→	if os.Getenv("CI") == "" {
 97→		return nil
 98→	}
 99→	apiKey := os.Getenv("ANTHROPIC_API_KEY")
100→	if apiKey == "" {
101→		return nil
102→	}
103→	home, err := os.UserHomeDir()
104→	if err != nil {
105→		return fmt.Errorf("get home dir: %w", err)
106→	}
107→	dir := filepath.Join(home, ".claude")
108→	if err := os.MkdirAll(dir, 0o755); err != nil {
109→		return fmt.Errorf("mkdir %s: %w", dir, err)
110→	}
111→	config := fmt.Sprintf(`{"primaryApiKey":%q,"hasCompletedOnboarding":true}`, apiKey)
112→	path := filepath.Join(dir, ".claude.json")
113→	return os.WriteFile(path, []byte(config), 0o644)
114→}
