181→func (c *Claude) StartSession(ctx context.Context, dir string) (Session, error) {
182→	name := fmt.Sprintf("claude-test-%d", time.Now().UnixNano())
183→
184→	envArgs := []string{
185→		"ACCESSIBLE=1",
186→		"ENTIRE_TEST_TTY=0",
187→
188→		// See https://code.claude.com/docs/en/settings - without this setting Claude was going off and
189→		// trying to Git-clone its plugin marketplace, which meant calling git commands that could fail
190→		// due to a user's exotic config (e.g. in paul's case, needing SSH-keychain access granted every
191→		// time).  That's no good, so for the E2E tests, we tell Claude not to make calls to auto-update
192→		// itself, clone its plugins, etc.
193→		"CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC=1",
194→	}
195→
196→	// On CI (no macOS Keychain), use an isolated config dir so Claude Code
197→	// picks up ANTHROPIC_API_KEY from the environment instead of trying OAuth.
198→	// Locally, we skip CLAUDE_CONFIG_DIR so the Keychain-based auth works.
199→	var configDir string
200→	if os.Getenv("CI") != "" {
201→		var err error
202→		configDir, err = isolatedConfigDir()
203→		if err == nil {
204→			envArgs = append(envArgs, "CLAUDE_CONFIG_DIR="+configDir)
205→		}
206→	}
207→
208→	args := append([]string{"env"}, envArgs...)
209→	args = append(args, c.Binary(), "--dangerously-skip-permissions")
210→	s, err := NewTmuxSession(name, dir, []string{"CLAUDECODE"}, args[0], args[1:]...)
211→	if err != nil {
212→		if configDir != "" {
213→			_ = os.RemoveAll(configDir)
214→		}
215→		return nil, err
216→	}
217→	if configDir != "" {
218→		s.OnClose(func() { _ = os.RemoveAll(configDir) })
219→	}
220→
221→	// Dismiss startup dialogs until we reach the input prompt.
222→	for range 5 {
223→		content, err := s.WaitFor(`❯`, 15*time.Second)
224→		if err != nil {
225→			_ = s.Close()
226→			return nil, fmt.Errorf("waiting for startup prompt: %w", err)
227→		}
228→		if !strings.Contains(content, "Enter to confirm") {
229→			break
230→		}
231→		// The bypass permissions dialog defaults to "No, exit" —
232→		// arrow down to "Yes, I accept" before confirming.
233→		if strings.Contains(content, "Yes, I accept") {
234→			_ = s.SendKeys("Down")
235→			time.Sleep(200 * time.Millisecond)
236→		}
237→		_ = s.SendKeys("Enter")
238→		time.Sleep(500 * time.Millisecond)
239→	}
240→	s.stableAtSend = ""
241→
242→	return s, nil
243→}
