 78→// stableContent returns the content with the last few lines stripped,
 79→// so that TUI status bar updates don't prevent the settle timer.
 80→func stableContent(content string) string {
 81→	lines := strings.Split(content, "\n")
 82→	if len(lines) > 3 {
 83→		lines = lines[:len(lines)-3]
 84→	}
