func TestInteractiveContentOverlapRevertNewFile(t *testing.T) {
	testutil.ForEachAgent(t, 2*time.Minute, func(t *testing.T, s *testutil.RepoState, ctx context.Context) {
		// Deny git commit via OpenCode permissions so the agent can't
		// auto-commit (prompt instructions alone are unreliable).
		testutil.WriteOpenCodeConfig(t, s.Dir, map[string]any{
			"permission": map[string]any{
				"bash": map[string]any{
					"*":            "allow",
					"git commit *": "deny",
				},
			},
		})

		prompt := s.Agent.PromptPattern()

		session := s.StartSession(t, ctx)
		if session == nil {
			t.Skipf("agent %s does not support interactive mode", s.Agent.Name())
		}

		s.WaitFor(t, session, prompt, 30*time.Second)

		s.Send(t, session, "create a markdown file at docs/red.md with a paragraph about the colour red. Do not commit. Do not run git. Just write the file.")
